inputs.body:
Cell{
  lock: { codeHash: ACP,
          args: {{pubkey_hash 20B}} ‖ ckb_min? ‖ udt_min? }
}

Cell{
  lock: ACP(args),
  capacity: {{C}},
  type: T?,
  data: {{udt u128}} (T) / empty
}

outputs.body:
Cell{
  lock: ACP(args),
  type: same T,
  capacity: {{≥ C + 10^ckb_min}}  or = C,
  udt:      {{≥ U + 10^udt_min}}  or = U
}
